import { useState, useEffect } from 'react';
import { Shield, FolderSearch, Activity, Settings, Cpu, ShieldAlert, Download } from 'lucide-react';
import { VulnerabilityReport, Vulnerability } from './components/VulnerabilityReport';
import './assets/main.css';

function App() {
  const [selectedPath, setSelectedPath] = useState<string | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [scanProgress, setScanProgress] = useState(0);
  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  const [modelReady, setModelReady] = useState(false);
  const [showSetup, setShowSetup] = useState(true);
  const [setupStatus, setSetupStatus] = useState<string>('Ready to download or connect model...');

  useEffect(() => {
    let interval: any = null;
    const checkModel = async () => {
      try {
        if (window.electron?.ipcRenderer) {
          const status = await window.electron.ipcRenderer.invoke('check-model-status');
          if (status.ready) {
            setModelReady(true);
            setShowSetup(false);
          }
        }
      } catch (err) {
        console.error(err);
      }
    };

    checkModel();
    interval = setInterval(checkModel, 2000);
    return () => {
      if (interval) clearInterval(interval);
    };
  }, []);

  const handleSelectDirectory = async () => {
    if (!window.electron?.ipcRenderer) {
      // Mock for browser dev
      setSelectedPath('/mock/path/to/project');
      return;
    }
    const path = await window.electron.ipcRenderer.invoke('select-directory');
    if (path) {
      setSelectedPath(path);
      setVulnerabilities([]);
      setScanProgress(0);
    }
  };

  const handleStartScan = async () => {
    if (!selectedPath) return;
    setIsScanning(true);
    setScanProgress(10);
    setVulnerabilities([]);

    if (window.electron?.ipcRenderer) {
      window.electron.ipcRenderer.on('scan-progress', (_, progress, newVuln) => {
        setScanProgress(progress);
        if (newVuln) {
          setVulnerabilities(prev => [...prev, newVuln]);
        }
      });

      const results = await window.electron.ipcRenderer.invoke('start-scan', selectedPath);
      setVulnerabilities(results);
      setScanProgress(100);
      setIsScanning(false);
      window.electron.ipcRenderer.removeAllListeners('scan-progress');
    } else {
      // Mock scan
      setTimeout(() => setScanProgress(40), 1000);
      setTimeout(() => setScanProgress(80), 2000);
      setTimeout(() => {
        setScanProgress(100);
        setVulnerabilities([
          {
            id: '1',
            title: 'SQL Injection Risk',
            severity: 'high',
            file: 'src/api/users.ts:45',
            description: 'Direct concatenation of user input into SQL query string.',
            snippet: "const query = `SELECT * FROM users WHERE username = '${req.body.username}'`;",
            recommendation: 'Use parameterized queries or an ORM to prevent SQL injection.'
          }
        ]);
        setIsScanning(false);
      }, 3000);
    }
  };

  const handleSetupModel = async () => {
    setSetupStatus('Downloading Phi-4 Mini (Mocking...)');
    setTimeout(() => {
      setSetupStatus('Model Ready!');
      setModelReady(true);
      setTimeout(() => setShowSetup(false), 1000);
    }, 2000);
  };

  const handleExportPdf = async () => {
    if (window.electron?.ipcRenderer) {
      const result = await window.electron.ipcRenderer.invoke('export-pdf');
      if (result.success) {
        alert('Report saved to ' + result.filePath);
      } else if (!result.canceled) {
        alert('Failed to save report: ' + result.error);
      }
    }
  };

  return (
    <>
      {showSetup && (
        <div className="modal-overlay">
          <div className="glass-panel modal-content" style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', alignItems: 'center', textAlign: 'center' }}>
            <Cpu size={48} color="var(--accent-color)" />
            <h2>Local AI Model Setup</h2>
            <p style={{ color: 'var(--text-secondary)' }}>
              ODAVA requires a local Small Language Model (SLM) like Phi-4 Mini to analyze your code without sending it to the cloud.
            </p>
            <div style={{ background: 'rgba(0,0,0,0.4)', padding: '12px', borderRadius: '8px', width: '100%', fontSize: '0.9rem' }}>
              {setupStatus}
            </div>
            <div style={{ display: 'flex', gap: '1rem', width: '100%', marginTop: '1rem' }}>
              <button className="btn-outline" style={{ flex: 1 }} onClick={() => setShowSetup(false)}>Skip for now</button>
              <button className="btn-primary" style={{ flex: 1, justifyContent: 'center' }} onClick={handleSetupModel}>
                Download Model
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="app-container">
        <header>
          <div className="logo-container">
            <div className="logo-icon">
              <Shield size={24} />
            </div>
            <div>
              <h1 className="app-title">ODAVA <span className="text-gradient">Core</span></h1>
              <span className="app-subtitle">On-Device AI Vulnerability Analyzer</span>
            </div>
          </div>
          <div>
            <button className="btn-outline" onClick={() => setShowSetup(true)} style={{ padding: '8px', borderRadius: '50%' }}>
              <Settings size={20} />
            </button>
          </div>
        </header>

        <div className="dashboard-grid">
          <div className="controls-panel">
            <div className="glass-panel" style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              <h3 style={{ fontSize: '1.1rem', marginBottom: '0.5rem' }}>Scan Target</h3>
              <button className="btn-outline" onClick={handleSelectDirectory}>
                <FolderSearch size={18} /> Select Codebase
              </button>

              {selectedPath ? (
                <div className="path-display">
                  {selectedPath}
                </div>
              ) : (
                <div className="path-display" style={{ opacity: 0.5, fontStyle: 'italic' }}>
                  No directory selected
                </div>
              )}

              <button 
                className="btn-primary" 
                style={{ justifyContent: 'center', marginTop: '1rem' }}
                disabled={!selectedPath || isScanning}
                onClick={handleStartScan}
              >
                <Activity size={18} />
                {isScanning ? 'Analyzing...' : 'Start Scan'}
              </button>
            </div>

            <div className="glass-panel status-card">
              <h3 style={{ fontSize: '1.1rem', marginBottom: '1rem' }}>System Status</h3>
              <div className="status-indicator">
                <div className={`status-dot ${modelReady ? 'success' : 'danger'}`}></div>
                <span>AI Inference Engine: {modelReady ? 'Online' : 'Offline'}</span>
              </div>
              <div className="status-indicator">
                <div className={`status-dot ${isScanning ? 'active' : ''}`}></div>
                <span>Scanner: {isScanning ? 'Active' : 'Idle'}</span>
              </div>

              {isScanning && (
                <div className="progress-container">
                  <div className="progress-bar" style={{ width: `${scanProgress}%` }}></div>
                </div>
              )}
            </div>
          </div>

          <div className="glass-panel" style={{ display: 'flex', flexDirection: 'column', height: '100%', overflow: 'hidden' }}>
            <h2 style={{ fontSize: '1.3rem', marginBottom: '1.5rem', display: 'flex', alignItems: 'center', gap: '8px' }}>
              <ShieldAlert size={22} color="var(--accent-hover)" />
              Scan Results 
              {vulnerabilities.length > 0 && (
                <div style={{ marginLeft: 'auto', display: 'flex', gap: '12px', alignItems: 'center' }}>
                  <span className="badge high">{vulnerabilities.length} Found</span>
                  <button className="btn-outline no-print" style={{ padding: '6px 12px', fontSize: '0.8rem' }} onClick={handleExportPdf}>
                    <Download size={14} /> Export PDF
                  </button>
                </div>
              )}
            </h2>

            <div style={{ flex: 1, overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>
              {selectedPath && !isScanning && vulnerabilities.length === 0 ? (
                <div className="flex-center" style={{ height: '100%', color: 'var(--text-secondary)' }}>
                  Ready to scan {selectedPath.split(/[\\/]/).pop()}
                </div>
              ) : !selectedPath ? (
                <div className="flex-center" style={{ height: '100%', color: 'var(--text-secondary)' }}>
                  Select a codebase to begin analysis.
                </div>
              ) : (
                <VulnerabilityReport vulns={vulnerabilities} />
              )}
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

export default App;

import { useState } from 'react'

function Versions(): React.JSX.Element {
  const [versions] = useState(window.electron.process.versions)

  return (
    <ul className="versions">
      <li className="electron-version">Electron v{versions.electron}</li>
      <li className="chrome-version">Chromium v{versions.chrome}</li>
      <li className="node-version">Node v{versions.node}</li>
    </ul>
  )
}

export default Versions

import { AlertTriangle, FileCode, CheckCircle, ShieldAlert } from 'lucide-react';

export interface Vulnerability {
  id: string;
  title: string;
  severity: 'high' | 'medium' | 'low';
  file: string;
  description: string;
  snippet: string;
  recommendation: string;
}

export function VulnerabilityReport({ vulns }: { vulns: Vulnerability[] }) {
  if (vulns.length === 0) {
    return (
      <div className="flex-center" style={{ height: '100%', flexDirection: 'column', gap: '1rem', color: 'var(--text-secondary)' }}>
        <CheckCircle size={48} color="var(--success)" />
        <p>No vulnerabilities found in the scanned codebase.</p>
      </div>
    );
  }

  return (
    <div className="results-area">
      {vulns.map((vuln) => (
        <div key={vuln.id} className={`glass-panel vuln-item ${vuln.severity}`}>
          <div className="vuln-header">
            <h3 className="vuln-title flex-center" style={{ gap: '8px' }}>
              {vuln.severity === 'high' ? <ShieldAlert size={20} color="var(--danger)" /> : <AlertTriangle size={20} />}
              {vuln.title}
            </h3>
            <span className={`badge ${vuln.severity}`}>{vuln.severity}</span>
          </div>

          <div className="vuln-file flex-center" style={{ gap: '6px', justifyContent: 'flex-start', marginBottom: '12px', display: 'inline-flex' }}>
            <FileCode size={14} />
            {vuln.file}
          </div>

          <p className="vuln-desc">{vuln.description}</p>

          <div className="code-snippet" style={{ marginBottom: '12px' }}>
            <code>{vuln.snippet}</code>
          </div>

          <div style={{ fontSize: '0.9rem' }}>
            <strong style={{ color: 'var(--accent-hover)' }}>Recommendation:</strong> {vuln.recommendation}
          </div>
        </div>
      ))}
    </div>
  );
}

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Fira+Code:wght@400;500&display=swap');

:root {
  --bg-primary: #0a0a0c;
  --bg-secondary: #141417;
  --bg-panel: rgba(255, 255, 255, 0.03);
  --border-color: rgba(255, 255, 255, 0.08);

  --text-primary: #f0f0f2;
  --text-secondary: #9a9a9c;

  --accent-color: #6366f1;
  --accent-hover: #818cf8;
  --accent-glow: rgba(99, 102, 241, 0.3);

  --success: #22c55e;
  --warning: #eab308;
  --danger: #ef4444;
  --danger-glow: rgba(239, 68, 68, 0.2);

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  overflow-x: hidden;
}

/* Glassmorphism Panel */
.glass-panel {
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  backdrop-filter: blur(12px);
  border-radius: var(--radius-md);
  padding: 24px;
}

/* Utilities */
.flex-center {
  display: flex;
  align-items: center;
  justify-content: center;
}

.text-gradient {
  background: linear-gradient(135deg, #818cf8, #c084fc);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* Button */
.btn-primary {
  background: linear-gradient(135deg, var(--accent-color), #4f46e5);
  color: white;
  border: none;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: 0 4px 14px var(--accent-glow);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(99, 102, 241, 0.5);
  background: linear-gradient(135deg, var(--accent-hover), #6366f1);
}

.btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

.btn-outline {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn-outline:hover {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.2);
}

/* Layout */
.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  padding: 2rem;
  max-width: 1200px;
  margin: 0 auto;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}

.logo-container {
  display: flex;
  align-items: center;
  gap: 12px;
}

.logo-icon {
  width: 40px;
  height: 40px;
  background: linear-gradient(135deg, #818cf8, #c084fc);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  box-shadow: 0 4px 12px rgba(192, 132, 252, 0.3);
}

.app-title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.app-subtitle {
  font-size: 0.85rem;
  color: var(--text-secondary);
  font-weight: 500;
}

/* Dashboard Grid */
.dashboard-grid {
  display: grid;
  grid-template-columns: 350px 1fr;
  gap: 1.5rem;
  flex: 1;
  min-height: 0;
}

/* Sidebar / Controls */
.controls-panel {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.path-display {
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid var(--border-color);
  padding: 12px;
  border-radius: var(--radius-sm);
  font-family: 'Fira Code', monospace;
  font-size: 0.85rem;
  color: var(--text-secondary);
  word-break: break-all;
}

/* Scanner Status */
.status-card {
  position: relative;
  overflow: hidden;
}

.status-indicator {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 1rem;
}

.status-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--text-secondary);
}

.status-dot.active {
  background: var(--accent-color);
  box-shadow: 0 0 12px var(--accent-color);
  animation: pulse 2s infinite;
}

.status-dot.danger {
  background: var(--danger);
  box-shadow: 0 0 12px var(--danger);
}

.status-dot.success {
  background: var(--success);
  box-shadow: 0 0 12px var(--success);
}

@keyframes pulse {
  0% { box-shadow: 0 0 0 0 var(--accent-glow); }
  70% { box-shadow: 0 0 0 10px rgba(99, 102, 241, 0); }
  100% { box-shadow: 0 0 0 0 rgba(99, 102, 241, 0); }
}

/* Progress Bar */
.progress-container {
  width: 100%;
  height: 6px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
  overflow: hidden;
  margin-top: 1rem;
}

.progress-bar {
  height: 100%;
  background: linear-gradient(90deg, var(--accent-color), #c084fc);
  width: 0%;
  transition: width 0.3s ease;
}

/* Results Area */
.results-area {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  overflow-y: auto;
  padding-right: 8px;
}

.results-area::-webkit-scrollbar {
  width: 6px;
}
.results-area::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.02);
}
.results-area::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
}

/* Vulnerability Item */
.vuln-item {
  border-left: 4px solid var(--danger);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.vuln-item:hover {
  transform: translateX(4px);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
}

.vuln-item.high { border-color: var(--danger); }
.vuln-item.medium { border-color: var(--warning); }
.vuln-item.low { border-color: var(--success); }

.vuln-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 0.5rem;
}

.vuln-title {
  font-weight: 600;
  font-size: 1.1rem;
  color: var(--text-primary);
}

.vuln-file {
  font-family: 'Fira Code', monospace;
  font-size: 0.8rem;
  color: var(--text-secondary);
  background: rgba(0, 0, 0, 0.4);
  padding: 4px 8px;
  border-radius: 4px;
}

.vuln-desc {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.5;
  margin-bottom: 1rem;
}

.code-snippet {
  background: #000;
  border: 1px solid var(--border-color);
  padding: 12px;
  border-radius: var(--radius-sm);
  font-family: 'Fira Code', monospace;
  font-size: 0.85rem;
  overflow-x: auto;
}

.badge {
  padding: 4px 8px;
  border-radius: 12px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.badge.high { background: var(--danger-glow); color: var(--danger); }
.badge.medium { background: rgba(234, 179, 8, 0.2); color: var(--warning); }
.badge.low { background: rgba(34, 197, 94, 0.2); color: var(--success); }

/* Model Setup Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.8);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  animation: fadeIn 0.3s ease;
}

.modal-content {
  width: 100%;
  max-width: 500px;
  position: relative;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.spinner {
  width: 20px;
  height: 20px;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-radius: 50%;
  border-top-color: white;
  animation: spin 1s ease-in-out infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@media print {
  .sidebar, .status-card, .no-print, .btn-primary, .btn-outline {
    display: none !important;
  }

  body, .app-container, .main-content, .glass-panel {
    background: white !important;
    color: black !important;
    box-shadow: none !important;
    border: none !important;
    height: auto !important;
    overflow: visible !important;
  }

  .vuln-card {
    background: white !important;
    border: 1px solid #ccc !important;
    page-break-inside: avoid;
    color: black !important;
    box-shadow: none !important;
  }

  .vuln-card pre {
    background: #f5f5f5 !important;
    color: #333 !important;
    border: 1px solid #ddd !important;
  }

  .badge {
    border: 1px solid #666;
  }
}

:root {
  --ev-c-white: #ffffff;
  --ev-c-white-soft: #f8f8f8;
  --ev-c-white-mute: #f2f2f2;

  --ev-c-black: #1b1b1f;
  --ev-c-black-soft: #222222;
  --ev-c-black-mute: #282828;

  --ev-c-gray-1: #515c67;
  --ev-c-gray-2: #414853;
  --ev-c-gray-3: #32363f;

  --ev-c-text-1: rgba(255, 255, 245, 0.86);
  --ev-c-text-2: rgba(235, 235, 245, 0.6);
  --ev-c-text-3: rgba(235, 235, 245, 0.38);

  --ev-button-alt-border: transparent;
  --ev-button-alt-text: var(--ev-c-text-1);
  --ev-button-alt-bg: var(--ev-c-gray-3);
  --ev-button-alt-hover-border: transparent;
  --ev-button-alt-hover-text: var(--ev-c-text-1);
  --ev-button-alt-hover-bg: var(--ev-c-gray-2);
}

:root {
  --color-background: var(--ev-c-black);
  --color-background-soft: var(--ev-c-black-soft);
  --color-background-mute: var(--ev-c-black-mute);

  --color-text: var(--ev-c-text-1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  font-weight: normal;
}

ul {
  list-style: none;
}

body {
  min-height: 100vh;
  color: var(--color-text);
  background: var(--color-background);
  line-height: 1.6;
  font-family:
    Inter,
    -apple-system,
    BlinkMacSystemFont,
    'Segoe UI',
    Roboto,
    Oxygen,
    Ubuntu,
    Cantarell,
    'Fira Sans',
    'Droid Sans',
    'Helvetica Neue',
    sans-serif;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
